from pathlib import Path
CHAT=-1002373696859
THREAD=4640
URL="https://t.me/CreateVdobot?start=sticker"
if Path.cwd().resolve().name!='create-videobot':
 print("STK04_CREATOR_OWNER_WRONG");sys.exit(61)
token_pattern=re.compile(r"^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$")
