for directory in (Path.cwd()/'deploy'/'secrets',Path.cwd()/'deploy',Path.home()/'.config'/'create-videobot'):
 if not directory.is_dir():continue
 for f in directory.iterdir():
  try:
   if not f.is_file() or f.is_symlink():continue
