   elif len(raw)<8192:
    for line in raw.splitlines():
     if line.lstrip().startswith('#') or '=' not in line:continue
     key,val=line.split('=',1)
     if 'TOKEN' in key.upper() and any(k in key.upper() for k in ('CREATE','VIDEO','VDO','TELEGRAM')):
      val=val.strip().strip('"').strip("'")
