 try:
  with urllib.request.urlopen(req,timeout=15) as res:r=json.load(res)
 except urllib.error.HTTPError as e:
  raise ValueError("API_"+method+"_REJECTED_"+str(e.code))
 except Exception:
  raise RuntimeError("API_"+method+"_RESULT_UNKNOWN")
 if r.get('ok') is not True:raise ValueError("API_"+method+"_REJECTED_"+str(r.get('error_code','UNKNOWN')))
 return r.get('result')
