with (base/'group2373696859_thread4640.lock').open('w') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 state=json.loads(receipt.read_text()) if receipt.exists() else None
 def persist(status,mid=None):
