 if result is not True:
  persist('needs_reconcile',mid);print("STK04_PIN_ACK_NOT_TRUE");sys.exit(72)
 persist('pinned_ack',mid)
 print("STK04_CREATOR_PIN_API_ACK=PASS")
 print("STK04_CREATOR_MESSAGE_ID="+str(mid))
